import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec

// 密钥从场景属性 hmacSecretKey 读取，避免明文写入脚本
def secret = '${__P(hmacSecretKey)}'
def plainText = vars.get('requestBody') ?: ''
def mac = Mac.getInstance('HmacSHA256')
mac.init(new SecretKeySpec(secret.getBytes('UTF-8'), 'HmacSHA256'))
def signature = mac.doFinal(plainText.getBytes('UTF-8')).encodeHex().toString()
vars.put('hmacSignature', signature)
log.info('HMAC-SHA256 签名生成成功')

import javax.crypto.Cipher
import javax.crypto.spec.SecretKeySpec

// 密钥从场景属性 aesSecretKey 读取，避免明文写入脚本
def key = '${__P(aesSecretKey)}'
def plainText = vars.get('requestBody') ?: ''
def cipher = Cipher.getInstance('AES/ECB/PKCS5Padding')
cipher.init(Cipher.ENCRYPT_MODE, new SecretKeySpec(key.getBytes('UTF-8'), 'AES'))
def encrypted = cipher.doFinal(plainText.getBytes('UTF-8')).encodeBase64().toString()
vars.put('encryptedBody', encrypted)
log.info('AES-256 加密完成')

import java.security.KeyFactory
import java.security.Signature
import java.security.spec.PKCS8EncodedKeySpec

// 私钥从场景属性 rsaPrivateKey 读取，避免明文写入脚本
def privateKeyBase64 = '${__P(rsaPrivateKey)}'
def plainText = vars.get('requestBody') ?: ''
def keyBytes = java.util.Base64.getDecoder().decode(privateKeyBase64)
def privateKey = KeyFactory.getInstance('RSA').generatePrivate(new PKCS8EncodedKeySpec(keyBytes))
def signer = Signature.getInstance('SHA256withRSA')
signer.initSign(privateKey)
signer.update(plainText.getBytes('UTF-8'))
vars.put('rsaSignature', java.util.Base64.getEncoder().encodeToString(signer.sign()))
log.info('RSA SHA256withRSA 签名生成成功')

// 前缀从场景属性 orderNoPrefix 读取
def prefix = '${__P(orderNoPrefix)}'
def orderId = prefix + UUID.randomUUID().toString().replace('-', '') + System.currentTimeMillis()
vars.put('orderId', orderId)
vars.put('timestampMillis', String.valueOf(System.currentTimeMillis()))
log.info('生成唯一单号：' + orderId)
